// Release approval rules.
import { ApprovalError } from "./approval-errors.ts";

export interface Release {
  readonly id: string;
  readonly authorId: string;
}

export interface ApprovalStore {
  append(event: { readonly releaseId: string; readonly userId: string }): Promise<void>;
  markReleased(releaseId: string): Promise<void>;
}

export interface DeskOptions {
  readonly store: ApprovalStore;
  readonly quorum: number;
  readonly roles: ReadonlyMap<string, readonly string[]>;
}

export interface ApprovalResult {
  readonly approvals: number;
  readonly released: boolean;
}

export function hasQuorum(approverIds: readonly string[], quorum: number): boolean {
  return new Set(approverIds).size >= quorum;
}

export function createApprovalDesk(options: DeskOptions) {
  if (!Number.isInteger(options.quorum) || options.quorum < 2) {
    throw new RangeError("quorum must be an integer >= 2");
  }
  const approvers = new Map<string, Set<string>>();
  const released = new Set<string>();

  function authorize(release: Release, userId: string): void {
    if (userId === release.authorId) throw new ApprovalError("self_approval", "authors cannot approve their own release");
    const userRoles = options.roles.get(userId) ?? [];
    if (!userRoles.includes("maintainer")) throw new ApprovalError("not_maintainer", "only maintainers can approve");
  }

  function approversOf(releaseId: string): Set<string> {
    let current = approvers.get(releaseId);
    if (current === undefined) {
      current = new Set<string>();
      approvers.set(releaseId, current);
    }
    return current;
  }

  return {
    async approve(release: Release, userId: string): Promise<ApprovalResult> {
      authorize(release, userId);
      const current = approversOf(release.id);
      if (!current.has(userId)) {
        try {
          await options.store.append({ releaseId: release.id, userId });
        } catch (error) {
          throw new ApprovalError("storage", `could not record the approval: ${String(error)}`);
        }
        current.add(userId);
      }
      const reached = hasQuorum([...current], options.quorum);
      if (reached && !released.has(release.id)) {
        released.add(release.id);
        await options.store.markReleased(release.id);
      }
      return { approvals: current.size, released: reached };
    },
  };
}

