// Runs a batch of asynchronous steps in order, retrying steps that fail with a retryable error.
export interface Step {
  readonly name: string;
  run(): Promise<void>;
}

export type RunResult =
  | { readonly status: "ok"; readonly attempts: number }
  | { readonly status: "failed"; readonly failedStep: string; readonly attempts: number; readonly error: unknown };

export interface StepEvent {
  readonly step: string;
  readonly attempt: number;
  readonly outcome: "ok" | "retry" | "fail";
}

export interface RunnerOptions {
  readonly maxAttempts: number;
  readonly sleep: (attempt: number) => Promise<void>;
  readonly onEvent?: (event: StepEvent) => void;
}

export class RunnerBusyError extends Error {
  constructor() {
    super("a batch is already running");
    this.name = "RunnerBusyError";
  }
}

function isRetryable(error: unknown): boolean {
  return typeof error === "object" && error !== null && (error as { retryable?: unknown }).retryable === true;
}

async function runBatch(steps: readonly Step[], options: RunnerOptions): Promise<RunResult> {
  let attempts = 0;
  for (const step of steps) {
    for (let attempt = 1; ; attempt++) {
      attempts += 1;
      try {
        await step.run();
        options.onEvent?.({ step: step.name, attempt, outcome: "ok" });
        break;
      } catch (error) {
        const retry = isRetryable(error) && attempt < options.maxAttempts;
        options.onEvent?.({ step: step.name, attempt, outcome: retry ? "retry" : "fail" });
        if (!retry) return { status: "failed", failedStep: step.name, attempts, error };
      }
      await options.sleep(attempt);
    }
  }
  return { status: "ok", attempts };
}

export function createRunner(options: RunnerOptions) {
  if (!Number.isInteger(options.maxAttempts) || options.maxAttempts < 1) {
    throw new RangeError("maxAttempts must be an integer >= 1");
  }
  let busy = false;
  return {
    async run(steps: readonly Step[]): Promise<RunResult> {
      if (busy) throw new RunnerBusyError();
      busy = true;
      try {
        return await runBatch(steps, options);
      } finally {
        busy = false;
      }
    },
  };
}
